contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address target, uint value) public payable {
        require(address(c).balance >= value, "not enough balance in c");

        uint beforeTarget = target.balance;
        uint beforeC = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.sendMoney(target, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterTarget = target.balance;
        uint afterC = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            (reverted && afterTarget == beforeTarget && afterC == beforeC && afterDeposits == beforeDeposits) ||
            (!reverted && afterTarget == beforeTarget + value && afterC == beforeC - value && afterDeposits == beforeDeposits)
        );
    }
}

