contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address target, uint256 value) internal {
        vm.assume(address(c).balance >= value);
        uint beforeTarget = target.balance;
        uint beforeC = address(c).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        bool reverted;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterTarget = target.balance;
        uint afterC = address(c).balance;
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        assertTrue((reverted && afterTarget == beforeTarget && afterC == beforeC && afterDeposits == beforeDeposits) ||
            (!reverted && afterTarget == beforeTarget + value && afterC == beforeC - value && afterDeposits == beforeDeposits));
